WITH valid_order_items AS (SELECT *, ROUND(quantity * 1.1, 2) AS quantity_adjusted FROM order_items WHERE order_id IN (1, 5, 10) AND quantity <> 3), OrderItemsStats AS (SELECT CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(DISTINCT unit_price) AS unique_products, MIN(quantity) AS min_quantity FROM valid_order_items GROUP BY CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, unique_products, min_quantity FROM OrderItemsStats WHERE min_quantity >= 4.8 ORDER BY unique_products
